@prefix : <https://w3id.org/ogc/utils/label/> .
@prefix dct: <http://purl.org/dc/terms/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ rdfs:label "IS II" ;
                    dct:hasPart [ :namePartType <http://www.example.com/nametypes/Stamp> ] ] ;
            sh:resultMessage "Value does not conform to Shape :NamePartShape" ;
            sh:resultPath dct:hasPart ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:NodeConstraintComponent ;
            sh:sourceShape :CompoundName-hasPart ;
            sh:value [ :namePartType <http://www.example.com/nametypes/Stamp> ] ] .

@prefix : <https://w3id.org/ogc/utils/label/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <http://www.example.com/measures/m1> ;
            sh:resultMessage "Less than 1 values on ex:m1->:value" ;
            sh:resultPath :value ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:decimal ;
                    sh:maxCount 1 ;
                    sh:minCount 1 ;
                    sh:path :value ] ] .

@prefix : <https://w3id.org/ogc/utils/label/> .
@prefix dct: <http://purl.org/dc/terms/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ rdfs:label "IS II - DP 3333" ;
                    dct:hasPart [ rdfs:label "IS II" ],
                        [ rdfs:label "DP 4444" ] ] ;
            sh:resultMessage "Name parts must exist in label if present" ;
            sh:resultPath rdfs:label ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "Name parts must exist in label if present" ;
                    sh:prefixes :prefixes ;
                    sh:select """
        SELECT $this (rdfs:label AS ?path) ?value
        WHERE {
          $this dct:hasPart ?p .
          $this rdfs:label ?label .
          ?p rdfs:label ?value
          FILTER ( ! CONTAINS( LCASE(?label), LCASE(?value)) )
        }
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape :CompoundName-partsInLabel ;
            sh:value "DP 4444" ] .

